#[summary("clamp: limit x to the closed range [lo, hi]")]
mod tasks {
    #[effects(pure)]
    #[uses(clamp_spec, lo_le_hi)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires lo_le_hi(lo, hi),
        ensures clamp_spec(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn clamp_spec(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        if x < lo {
            r == lo
        } else if x > hi {
            r == hi
        } else {
            r == x
        }
    }

    spec fn lo_le_hi(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("exact floor((a+b)/2) midpoint for i64")]
mod tasks {
    spec fn is_midpoint(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_midpoint)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_midpoint(a, b, r),
    {
        let qa: i64 = a / 2;
        let qb: i64 = b / 2;
        let ra: i64 = a % 2;
        let rb: i64 = b % 2;
        let base: i64 = qa + qb;
        let s: i64 = ra + rb;
        if s >= 2 {
            base + 1
        } else if s <= -1 {
            base - 1
        } else {
            base
        }
    }
}

