#[summary("sat_sum: left-to-right sum of an i64 slice, each addition saturating at i64::MIN/i64::MAX")]
mod tasks {
    spec fn is_sat_add_result(x: i64, y: i64, r: i64) -> bool {
        r == sat_add_spec(x, y)
    }

    spec fn is_sat_total(a: &[i64], r: i64) -> bool {
        r == sat_total(a, 0, 0)
    }

    #[effects(pure)]
    #[uses(is_sat_add_result, sat_add_spec)]
    fn sat_add(x: i64, y: i64) -> (r: i64)
        ensures is_sat_add_result(x, y, r),
    {
        if y > 0 && x > i64::MAX - y {
            i64::MAX
        } else if y < 0 && x < i64::MIN - y {
            i64::MIN
        } else {
            x + y
        }
    }

    spec fn sat_add_spec(x: i64, y: i64) -> i64 {
        if y > 0 && x > i64::MAX - y {
            i64::MAX
        } else if y < 0 && x < i64::MIN - y {
            i64::MIN
        } else {
            x + y
        }
    }

    #[effects(pure)]
    #[uses(is_sat_add_result, is_sat_total, sat_add_spec, sat_total)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_total(a, r),
    {
        let mut acc: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len(), sat_total(a, i, acc) == sat_total(a, 0, 0),
            decreases a.len() - i,
        {
            let n: i64 = sat_add(acc, a[i]);
            acc = n;
            i = i + 1;
        }
        acc
    }

    spec fn sat_total(a: &[i64], i: usize, acc: i64) -> i64
        decreases a.len() - i,
    {
        if i < a.len() {
            sat_total(a, i + 1, sat_add_spec(acc, a[i]))
        } else {
            acc
        }
    }
}

#[summary("count_in_range: number of elements x of a with lo <= x <= hi (0 if lo > hi)")]
mod tasks {
    #[effects(pure)]
    #[uses(counted, prefix_count)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures counted(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut count: usize = 0;
        while i < a.len()
            invariant i <= a.len(), count <= i, count == prefix_count(a, lo, hi, i),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                count = count + 1;
            }
            i = i + 1;
        }
        count
    }

    spec fn counted(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == prefix_count(a, lo, hi, a.len())
    }

    spec fn prefix_count(a: &[i64], lo: i64, hi: i64, i: usize) -> usize
        decreases i,
    {
        if i == 0 {
            0
        } else {
            (if lo <= a[i - 1] && a[i - 1] <= hi { 1 } else { 0 }) + prefix_count(a, lo, hi, i - 1)
        }
    }
}

#[summary("first_max_index: smallest index of a largest element of a non-empty i64 slice")]
mod tasks {
    #[effects(pure)]
    #[uses(is_first_max, nonempty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut j: usize = 1;
        while j < a.len()
            invariant j >= 1, j <= a.len(), best < j, forall|k: usize| k < j ==> #[trigger] a[k] <= a[best], forall|m: usize| m < best ==> #[trigger] a[m] < a[best],
            decreases a.len() - j,
        {
            if a[j] > a[best] {
                best = j;
            }
            j = j + 1;
        }
        best
    }

    spec fn is_first_max(a: &[i64], i: usize) -> bool {
        i < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[i] && (forall|k: usize| k < i ==> #[trigger] a[k] < a[i]))
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("Returns the index of the last occurrence of the minimum element of a non-empty slice")]
mod tasks {
    spec fn is_last_min(a: &[i64], i: usize) -> bool {
        i < a.len() && (forall|m: usize| 0 <= m && m < a.len() ==> #[trigger] a[m] >= a[i] && (forall|n: usize| 0 <= n && n < a.len() && #[trigger] a[n] == a[i] ==> n <= i))
    }

    #[effects(pure)]
    #[uses(is_last_min, nonempty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_last_min(a, r),
    {
        let mut best: usize = 0;
        let mut j: usize = 1;
        while j < a.len()
            invariant j <= a.len() && best < j && (forall|k: usize| 0 <= k && k < j ==> #[trigger] a[k] >= a[best] && (forall|h: usize| 0 <= h && h < j && #[trigger] a[h] == a[best] ==> h <= best)),
            decreases a.len() - j,
        {
            if a[j] <= a[best] {
                best = j;
            }
            j = j + 1;
        }
        best
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("check whether an i64 slice is strictly increasing")]
mod tasks {
    spec fn post(a: &[i64], r: bool) -> bool {
        r == strictly_increasing_spec(a)
    }

    #[effects(pure)]
    #[uses(post, strictly_increasing_spec)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures post(a, r),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        let mut bad: usize = 0;
        while ok && i < a.len() && i + 1 < a.len()
            invariant 0 <= i && i <= a.len(), ok ==> (forall|j: usize| j < i && j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]), !ok ==> bad < a.len() && bad + 1 < a.len() && !(a[bad] < a[bad + 1]),
            decreases a.len() - i,
        {
            if !(a[i] < a[i + 1]) {
                ok = false;
                bad = i;
            }
            i = i + 1;
        }
        ok
    }

    spec fn strictly_increasing_spec(a: &[i64]) -> bool {
        forall|i: usize| i + 1 < a.len() ==> #[trigger] a[i] < a[i + 1]
    }
}

#[summary("lower_bound: smallest index i with a[i] >= t in a non-decreasing i64 slice (binary search)")]
mod tasks {
    spec fn lb_spec(a: &[i64], t: i64, i: usize) -> bool {
        i <= a.len() && (forall|p: usize| 0 <= p && p < a.len() && p < i ==> #[trigger] (a[p] < t)) && (forall|q: usize| i <= q && q < a.len() ==> #[trigger] (a[q] >= t))
    }

    #[effects(pure)]
    #[uses(lb_spec, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures lb_spec(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant lo <= hi, hi <= a.len(), forall|p: usize| 0 <= p && p < lo && p < a.len() ==> #[trigger] (a[p] < t), forall|q: usize| hi <= q && q < a.len() ==> #[trigger] (a[q] >= t),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] >= t {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| 0 <= i && i < j && j < a.len() ==> #[trigger] (a[i] <= a[j])
    }
}

#[summary("floor division for i64")]
mod tasks {
    #[effects(pure)]
    #[uses(is_floor_quot, valid_input)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires valid_input(a, b),
        ensures is_floor_quot(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (a < 0 && b > 0 || a > 0 && b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn is_floor_quot(a: i64, b: i64, r: i64) -> bool {
        if b > 0 {
            r * b <= a && a < r * b + b
        } else {
            r * b + b < a && a <= r * b
        }
    }

    spec fn valid_input(a: i64, b: i64) -> bool {
        b != 0 && !(a == i64::MIN && b == -1)
    }
}

#[summary("mod_floor: a - b * floor(a / b), the floor-division remainder")]
mod tasks {
    spec fn is_mod_floor(a: i64, b: i64, r: i64) -> bool {
        (r == a % b || a % b != 0 && r == a % b + b) && (b > 0 && 0 <= r && r < b || b < 0 && b < r && r <= 0)
    }

    #[effects(pure)]
    #[uses(is_mod_floor, nonzero)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires nonzero(b),
        ensures is_mod_floor(a, b, r),
    {
        if b == -1 {
            0
        } else {
            let m: i64 = a % b;
            if m == 0 || (m > 0) == (b > 0) {
                m
            } else {
                m + b
            }
        }
    }

    spec fn nonzero(b: i64) -> bool {
        b != 0
    }
}

#[summary("second largest distinct value of a slice of i64; i64::MIN if fewer than two distinct values")]
mod tasks {
    spec fn above(a: &[i64], v: i64) -> bool {
        exists|i: usize| #[trigger] (a[i] > v) && i < a.len() && a[i] > v
    }

    spec fn agree_at_max(a: &[i64], m: i64, r: i64) -> bool {
        forall|k: usize| #[trigger] (a[k] == m) && k < a.len() ==> a[k] > r ==> a[k] == m
    }

    spec fn contains(a: &[i64], v: i64) -> bool {
        exists|i: usize| #[trigger] (a[i] == v) && i < a.len() && a[i] == v
    }

    spec fn has_two_distinct(a: &[i64]) -> bool {
        exists|i: usize| #[trigger] (i < a.len()) && i < a.len() && (exists|j: usize| #[trigger] (a[i] != a[j]) && j < a.len() && a[i] != a[j])
    }

    spec fn is_max(a: &[i64], m: i64) -> bool {
        prefix_max(a, a.len(), m)
    }

    spec fn prefix_max(a: &[i64], len: usize, m: i64) -> bool {
        len > 0 && (exists|i: usize| #[trigger] (a[i] == m) && i < len && a[i] == m && (forall|p: usize| #[trigger] (p < len) && p < len ==> a[p] <= m))
    }

    spec fn second_best_prefix(a: &[i64], len: usize, mx: i64, s: i64) -> bool {
        (s == i64::MIN || (exists|k: usize| #[trigger] (a[k] == s) && k < len && a[k] == s && a[k] < mx)) && (forall|q: usize| #[trigger] (q < len) && q < len ==> a[q] < mx ==> a[q] <= s)
    }

    #[effects(pure)]
    #[uses(above, contains, has_two_distinct, prefix_max, second_best_prefix, second_max_result, upper_bound_ok)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures second_max_result(a, r),
    {
        let n: usize = a.len();
        if n == 0 {
            i64::MIN
        } else {
            let mut mx: i64 = a[0];
            let mut i: usize = 1;
            while i < n
                invariant 1 <= i && i <= n && prefix_max(a, i, mx),
                decreases n - i,
            {
                if a[i] > mx {
                    mx = a[i];
                }
                i = i + 1;
            }
            let mut second: i64 = i64::MIN;
            let mut j: usize = 0;
            while j < n
                invariant j <= n && second_best_prefix(a, j, mx, second),
                decreases n - j,
            {
                if a[j] < mx {
                    if a[j] > second {
                        second = a[j];
                    }
                }
                j = j + 1;
            }
            second
        }
    }

    spec fn second_max_result(a: &[i64], r: i64) -> bool {
        (a.len() == 0 ==> r == i64::MIN) && (has_two_distinct(a) ==> contains(a, r) && above(a, r) && upper_bound_ok(a, r)) && (!has_two_distinct(a) ==> r == i64::MIN)
    }

    spec fn upper_bound_ok(a: &[i64], r: i64) -> bool {
        forall|k: usize| #[trigger] (k < a.len()) && k < a.len() ==> a[k] <= r || (forall|j: usize| #[trigger] (j < a.len()) && j < a.len() ==> a[j] <= a[k])
    }
}

