#[summary("greatest common divisor of |a| and |b|; gcd(0, 0) = 0")]
mod tasks {
    spec fn abs_i64(v: i64) -> i64 {
        if v < 0 {
            -v
        } else {
            v
        }
    }

    spec fn bounded(r: i64, a: i64, b: i64) -> bool {
        le(r, if abs_i64(a) <= abs_i64(b) { abs_i64(b) } else { abs_i64(a) }) && (abs_i64(a) > 0 && abs_i64(b) > 0 ==> le(r, if abs_i64(a) <= abs_i64(b) { abs_i64(a) } else { abs_i64(b) }))
    }

    spec fn common_div(c: i64, a: i64, b: i64) -> bool {
        c > 0 && a % c == 0 && b % c == 0
    }

    spec fn divs(d: i64, n: i64) -> bool {
        d > 0 && n % d == 0
    }

    #[effects(pure)]
    #[uses(le, le_pos, nonneg, pos_equiv, zero_tail)]
    fn egcd(a: i64, b: i64) -> (r: i64)
        requires le(b, a), nonneg(b),
        ensures le(r, a), nonneg(r), le_pos(r, b), pos_equiv(r, a), zero_tail(r, a, b),
        decreases b,
    {
        if b == 0 {
            a
        } else {
            egcd(b, a % b)
        }
    }

    #[effects(pure)]
    #[uses(abs_i64, bounded, gt_min, le, le_pos, nonneg, pos_equiv, zero_case, zero_iff, zero_tail)]
    fn gcd(a: i64, b: i64) -> (r: i64)
        requires gt_min(a), gt_min(b),
        ensures nonneg(r), zero_iff(r, a, b), bounded(r, a, b), zero_case(r, a, b),
    {
        let x: i64 = if a < 0 {
            -a
        } else {
            a
        };
        let y: i64 = if b < 0 {
            -b
        } else {
            b
        };
        if x <= y {
            let t: i64 = egcd(y, x);
            t
        } else {
            let u: i64 = egcd(x, y);
            u
        }
    }

    spec fn gcd_result(r: i64, a: i64, b: i64) -> bool {
        nonneg(r) && zero_iff(r, a, b) && le_max_abs(r, a, b) && zero_bounds(r, a, b)
    }

    spec fn gt_min(x: i64) -> bool {
        x > i64::MIN
    }

    spec fn is_gcd(r: i64, a: i64, b: i64) -> bool {
        a == 0 && b == 0 && r == 0 || r > 0 && a % r == 0 && b % r == 0 && (forall|c: i64| #[trigger] c > 0 && a % c == 0 && b % c == 0 ==> c <= r)
    }

    spec fn le(x: i64, y: i64) -> bool {
        x <= y
    }

    spec fn le_max_abs(r: i64, a: i64, b: i64) -> bool {
        le(r, if (if a < 0 { -a } else { a }) >= (if b < 0 { -b } else { b }) { if a < 0 { -a } else { a } } else { if b < 0 { -b } else { b } })
    }

    spec fn le_pos(r: i64, b: i64) -> bool {
        b > 0 ==> le(r, b)
    }

    spec fn nonneg(r: i64) -> bool {
        r >= 0
    }

    spec fn pos_equiv(r: i64, a: i64) -> bool {
        (r > 0) == (a > 0)
    }

    spec fn zero_bounds(r: i64, a: i64, b: i64) -> bool {
        (a == 0 ==> le(r, if b < 0 { -b } else { b })) && (b == 0 ==> le(r, if a < 0 { -a } else { a }))
    }

    spec fn zero_case(r: i64, a: i64, b: i64) -> bool {
        (b == 0 ==> r == abs_i64(a)) && (a == 0 ==> r == abs_i64(b))
    }

    spec fn zero_iff(r: i64, a: i64, b: i64) -> bool {
        (r == 0) == (a == 0 && b == 0)
    }

    spec fn zero_tail(r: i64, a: i64, b: i64) -> bool {
        b == 0 ==> r == a
    }
}

#[summary("integer square root: isqrt(n) is the largest r >= 0 with r*r <= n")]
mod tasks {
    #[effects(pure)]
    #[uses(isqrt_p, nonneg, search_inv)]
    fn isqrt(n: i64) -> (r: i64)
        requires nonneg(n),
        ensures isqrt_p(n, r),
    {
        let mut lo: i64 = 0;
        let mut hi: i64 = 3037000500;
        while lo < hi
            invariant search_inv(n, lo, hi),
            decreases hi - lo,
        {
            let mid: i64 = (lo + hi) / 2;
            if mid * mid <= n {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        hi - 1
    }

    spec fn isqrt_p(n: i64, r: i64) -> bool {
        r >= 0 && r * r <= n && (r + 1) * (r + 1) > n
    }

    spec fn nonneg(n: i64) -> bool {
        n >= 0
    }

    spec fn search_inv(n: i64, lo: i64, hi: i64) -> bool {
        0 <= lo && lo <= hi && hi <= 3037000500 && (lo == 0 || (lo - 1) * (lo - 1) <= n) && hi * hi > n
    }
}

#[summary("decimal digits of |n|; 0 has one digit")]
mod tasks {
    #[effects(pure)]
    #[uses(digits, result_ok)]
    fn count_digits(n: i64) -> (r: i64)
        ensures result_ok(n, r),
        decreases if n >= 0 { n } else { -n },
    {
        if n >= 10 {
            1 + count_digits(n / 10)
        } else if n <= -10 {
            1 + count_digits(n / 10)
        } else {
            1
        }
    }

    spec fn digits(n: i64) -> i64
        decreases if n >= 0 { n } else { -n },
    {
        if n >= 10 {
            1 + digits(n / 10)
        } else if n <= -10 {
            1 + digits(n / 10)
        } else {
            1
        }
    }

    #[uses(digits)]
    spec fn result_ok(n: i64, r: i64) -> bool {
        r == digits(n)
    }
}

#[summary("range_sum: sum of the half-open range [i, j) of a")]
mod tasks {
    spec fn domain_ok(a: &[i64], i: usize, j: usize, elems_ok: bool) -> bool {
        i <= j && j <= a.len() && a.len() <= 1000000 && elems_ok
    }

    spec fn elem_bounds(a: &[i64]) -> bool {
        forall|t: usize| #[trigger] elem_ok(a, t)
    }

    spec fn elem_ok(a: &[i64], t: usize) -> bool {
        t < a.len() ==> a[t] >= -1000000000000 && a[t] <= 1000000000000
    }

    spec fn inv_ok(a: &[i64], i: usize, k: usize, j: usize, s: i64) -> bool {
        i <= k && k <= j && is_sum(a, i, k, s) && within(s, k - i) && elem_ok(a, k)
    }

    spec fn is_sum(a: &[i64], i: usize, j: usize, r: i64) -> bool
        decreases j,
    {
        if i == j {
            r == 0
        } else {
            j > 0 && is_sum(a, i, j - 1, r - a[j - 1])
        }
    }

    #[effects(pure)]
    #[uses(domain_ok, elem_bounds, elem_ok, inv_ok, is_sum, within)]
    fn range_sum(a: &[i64], i: usize, j: usize) -> (r: i64)
        requires domain_ok(a, i, j, elem_bounds(a)),
        ensures is_sum(a, i, j, r),
    {
        let mut s: i64 = 0;
        let mut k: usize = i;
        while k < j
            invariant inv_ok(a, i, k, j, s),
            decreases j - k,
        {
            s = s + a[k];
            k = k + 1;
        }
        s
    }

    spec fn within(s: i64, n: usize) -> bool {
        -1000000000000 * n <= s && s <= 1000000000000 * n
    }
}

#[summary("majority: value occurring in more than a.len()/2 positions, else i64::MIN")]
mod tasks {
    spec fn all_values_nonmajor(a: &[i64]) -> bool {
        forall|p: usize| #[trigger] (p < a.len() ==> count(a, a[p]) <= a.len() / 2)
    }

    spec fn count(a: &[i64], v: i64) -> usize {
        count_suffix(a, v, 0)
    }

    spec fn count_suffix(a: &[i64], v: i64, i: usize) -> usize
        decreases a.len() - i,
    {
        if i >= a.len() {
            0
        } else {
            (if a[i] == v { 1 } else { 0 }) + count_suffix(a, v, i + 1)
        }
    }

    spec fn inner_inv(a: &[i64], v: i64, j: usize, c: usize) -> bool {
        c <= j && j <= a.len() && c + count_suffix(a, v, j) == count(a, v)
    }

    spec fn is_majority(a: &[i64], v: i64) -> bool {
        count(a, v) > a.len() / 2
    }

    #[effects(pure)]
    #[uses(all_values_nonmajor, count, count_suffix, inner_inv, is_majority, majority_result_ok, outer_inv_found, outer_inv_prefix)]
    fn majority(a: &[i64]) -> (r: i64)
        ensures majority_result_ok(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut found: bool = false;
        let mut ans: i64 = i64::MIN;
        while i < n && !found
            invariant outer_inv_found(a, found, ans), outer_inv_prefix(a, found, i),
            decreases n - i,
        {
            let v: i64 = a[i];
            let mut j: usize = 0;
            let mut c: usize = 0;
            while j < n
                invariant inner_inv(a, v, j, c),
                decreases n - j,
            {
                if a[j] == v {
                    c = c + 1;
                }
                j = j + 1;
            }
            if c > n / 2 {
                ans = v;
                found = true;
            }
            i = i + 1;
        }
        if found {
            ans
        } else {
            i64::MIN
        }
    }

    spec fn majority_result_ok(a: &[i64], r: i64) -> bool {
        is_majority(a, r) || r == i64::MIN && all_values_nonmajor(a)
    }

    spec fn outer_inv_found(a: &[i64], found: bool, ans: i64) -> bool {
        found ==> count(a, ans) > a.len() / 2
    }

    spec fn outer_inv_prefix(a: &[i64], found: bool, i: usize) -> bool {
        !found ==> (forall|p: usize| #[trigger] (p < i ==> count(a, a[p]) <= a.len() / 2))
    }
}

#[summary("longest run of consecutive equal elements in a slice")]
mod tasks {
    #[effects(pure)]
    #[uses(max_run_prefix, result_ok, run_len)]
    fn longest_run(a: &[i64]) -> (r: usize)
        ensures result_ok(a, r),
    {
        let mut best: usize = 0;
        let mut cur: usize = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant i <= a.len() && cur <= i && best == max_run_prefix(a, i) && (i >= 1 ==> cur == run_len(a, i - 1)),
            decreases a.len() - i,
        {
            if i == 0 || a[i] != a[i - 1] {
                cur = 1;
            } else {
                cur = cur + 1;
            }
            if cur > best {
                best = cur;
            }
            i = i + 1;
        }
        best
    }

    spec fn max_run_prefix(a: &[i64], i: usize) -> usize
        decreases i,
    {
        if i == 0 {
            0
        } else if run_len(a, i - 1) > max_run_prefix(a, i - 1) {
            run_len(a, i - 1)
        } else {
            max_run_prefix(a, i - 1)
        }
    }

    #[uses(max_run_prefix)]
    spec fn result_ok(a: &[i64], r: usize) -> bool {
        r == max_run_prefix(a, a.len())
    }

    spec fn run_len(a: &[i64], i: usize) -> usize
        decreases i,
    {
        if i == 0 {
            1
        } else if a[i] == a[i - 1] {
            run_len(a, i - 1) + 1
        } else {
            1
        }
    }
}

#[summary("In-place selection sort: sorts an i64 slice into non-decreasing order")]
mod tasks {
    #[uses(min_in_range)]
    spec fn inv_in(a: &[i64], i: usize, m: usize, j: usize) -> bool {
        i < a.len() && j >= i && j <= a.len() && min_in_range(a, i, m, j)
    }

    #[uses(prefix_sorted)]
    spec fn inv_out(a: &[i64], i: usize) -> bool {
        i <= a.len() && prefix_sorted(a, i) && (i > 0 ==> (forall|l: usize| l < a.len() ==> #[trigger] (i <= l ==> a[i - 1] <= a[l])))
    }

    spec fn min_in_range(a: &[i64], i: usize, m: usize, j: usize) -> bool {
        i <= m && m < a.len() && (forall|k: usize| i <= k && k < j ==> #[trigger] (a[m] <= a[k]))
    }

    #[uses(sorted)]
    spec fn post(a: &[i64], o: &[i64]) -> bool {
        sorted(a) && a.len() == o.len()
    }

    spec fn prefix_le_suffix(a: &[i64], i: usize) -> bool {
        i <= a.len() && (forall|k: usize, l: usize| k < i && l < a.len() ==> #[trigger] (a[k] <= a[l]))
    }

    spec fn prefix_sorted(a: &[i64], i: usize) -> bool {
        i <= a.len() && (forall|k: usize| k < i && k + 1 < i ==> #[trigger] (a[k] <= a[k + 1]))
    }

    #[effects(pure)]
    #[uses(inv_in, inv_out, min_in_range, post, prefix_sorted, sorted)]
    fn sort(a: &mut [i64]) -> ()
        ensures post(a, old(a)),
    {
        let mut i: usize = 0;
        while i < a.len()
            invariant inv_out(a, i),
            decreases a.len() - i,
        {
            let mut m: usize = i;
            let mut j: usize = i + 1;
            while j < a.len()
                invariant inv_in(a, i, m, j),
                decreases a.len() - j,
            {
                if a[j] < a[m] {
                    m = j;
                }
                j = j + 1;
            }
            let t: i64 = a[i];
            a[i] = a[m];
            a[m] = t;
            i = i + 1;
        }
    }

    #[uses(prefix_sorted)]
    spec fn sorted(a: &[i64]) -> bool {
        prefix_sorted(a, a.len())
    }
}
